    def fmt(m):
        return str(len(m)) + '\n' + '\n'.join(' '.join(map(str, r)) for r in m)
    def rnd(n, hi):
        return [[rng.randint(1, hi) for _ in range(n)] for _ in range(n)]
    tests = [fmt([[1]]), fmt([[10**9]]), fmt([[1, 2], [3, 4]]), fmt([[7, 7], [7, 7]])]
    for n in (3, 4, 5, 6, 7, 8):
        tests.append(fmt(rnd(n, 9)))
    tests.append(fmt(rnd(5, 10**9)))
    tests.append(fmt([[1] * 10 for _ in range(10)]))
    tests.append(fmt(rnd(100, 10**9)))
    tests.append(fmt(rnd(300, 10**9)))
    tests.append(fmt([[10**9] * 300 for _ in range(300)]))
    return tests

