        in.nextToken();
        int n = (int) in.nval;
        long[][] matrix = new long[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                in.nextToken();
                matrix[i][j] = (long) in.nval;
            }
        long[][] res = toUpperTriangular(matrix);
        StringBuilder sb = new StringBuilder();
        for (long[] row : res) {
            for (int j = 0; j < row.length; j++) sb.append(row[j]).append(j + 1 < row.length ? " " : "\n");
